    "l2.s4.t": "Система адаптується",
    "l2.s4.d": "«Наступного разу зроби 80 kg × 8.»",
    "l2.s5.t": "Ти бачиш прогрес",
    "l2.s5.d": "Об'єм, рекорди та регулярність тиждень за тижнем",
    "l2.who.title": "GYMS.LIFE для тебе, якщо…",
    "l2.who1.t": "Ти новачок",
    "l2.who1.d": "Не знаєш, що робити в залі — отримуєш чіткий план та відео інструкції.",
    "l2.who2.t": "Ти вже тренуєшся",
    "l2.who2.d": "Тобі потрібна структура та прогресія навантажень без вгадувань.",
    "l2.who3.t": "У тебе мало часу",
    "l2.who3.d": "Система створює тренування на 30–45 хв під твій графік.",
    "l2.who4.t": "Тренуєшся вдома",
    "l2.who4.d": "План адаптується під твій інвентар — від гумок до штанги.",
    "l2.faq.title": "Часті запитання",
    "l2.faq.q1": "Чи потрібен мені зал?",
    "l2.faq.a1": "Ні. GYMS.LIFE створює план для дому або залу на основі обладнання, яке в тебе є.",
    "l2.faq.q2": "Чи можна замінити вправу?",
    "l2.faq.a2": "Так. Система запропонує альтернативу на ту саму групу м'язів з твоїм обладнанням.",
    "l2.faq.q3": "Чи потрібна картка для тріалу на 7 днів?",
    "l2.faq.a3": "Ні. Реєструйся та користуйся всіма функціями 7 днів. Картка знадобиться лише якщо вирішиш продовжити.",
    "l2.faq.q4": "Чи можна скасувати підписку?",
    "l2.faq.a4": "Так, будь-коли в налаштуваннях аккаунту. Доступ залишиться до кінця оплаченого періоду.",
    "l2.faq.q5": "Чи мої дані в безпеці?",
    "l2.faq.a5": "Дані зашифровані та використовуються лише для твого плану. Ти можеш експортувати їх або видалити аккаунт будь-коли.",
    "l2.faq.q6": "Це медична порада?",
    "l2.faq.a6": "Ні. GYMS.LIFE — це інструмент для тренувань та харчування, а не медична послуга. Консультуйся з лікарем, якщо маєш застереження.",
