    "h2.why": "Чому немає кнопки «підключити Apple Health / Google Fit»?",
    "h2.whyText": "Apple Health не має веб-API — дані ніколи не залишають телефон без вашої дії, а Google Fit API закривається (без нових додатків, підтримка завершується у 2026). Тому ця сторінка пропонує три дієві варіанти: автоматичне надсилання з телефону (iOS Shortcuts / Health Connect), імпорт файлу та вимірювання камерою.",
