    "lg.nav.pricing": "Cennik",
    "lg.terms.title": "Regulamin świadczenia usług",
    "lg.terms.updated": "Ostatnia aktualizacja: 26 sierpnia 2026",
    "lg.terms.h1": "1. Sprzedawca",
    "lg.terms.p1": "Usługa GYMS.LIFE jest świadczona przez Aleksandr Smirnov (dalej – „my”). Korzystając z usługi, zawierasz umowę z tym sprzedawcą. Kontynuując korzystanie z usługi, akceptujesz niniejszy regulamin.",
    "lg.terms.h2": "2. Usługa",
    "lg.terms.p2": "GYMS.LIFE to platforma do treningu personalnego i planowania żywienia: plany treningowe, biblioteka ćwiczeń z instruktażami wideo, plany posiłków, harmonogram suplementacji, analizy zdrowotne i analiza techniki ćwiczeń. Usługa jest świadczona w stanie „tak jak jest”; nie gwarantujemy nieprzerwanego ani bezbłędnego działania. Treści nie stanowią porady medycznej — skonsultuj się z lekarzem przed zmianą aktywności fizycznej lub diety.",
    "lg.terms.h3": "3. Konto",
    "lg.terms.p3": "Musisz dbać o bezpieczeństwo swoich danych logowania i ponosisz odpowiedzialność za aktywność na swoim koncie. Podane przez Ciebie informacje muszą być dokładne.",
    "lg.terms.h4": "4. Płatności i subskrypcja",
    "lg.terms.p4a": "Proces zamawiania jest obsługiwany przez naszego sprzedawcę internetowego Paddle.com. Paddle.com jest Merchant of Record (oficjalnym sprzedawcą) dla wszystkich naszych zamówień. Paddle zapewnia pełną obsługę klienta w kwestiach płatności oraz przetwarza zwroty. Mechanizmy płatności, rozliczeń, podatków, anulowania i zwrotów regulują",
    "lg.terms.p4link": "Warunki zakupu Paddle",
    "lg.terms.p4b": "Subskrypcja odnawia się automatycznie na wybrany okres (tydzień / miesiąc / rok), dopóki jej nie anulujesz. Możesz zrezygnować w dowolnym momencie – dostęp zachowujesz do końca opłaconego okresu.",
    "lg.terms.h5": "5. Działania zabronione",
    "lg.terms.p5": "Zabrania się korzystania z usługi w sposób niezgodny z prawem, rozsyłania spamu, naruszania praw własności intelektualnej, prób naruszenia bezpieczeństwa (złośliwe oprogramowanie, skanowanie systemu, scraping danych) oraz kopiowania lub odsprzedaży treści usługi.",
    "lg.terms.h6": "6. Własność intelektualna",
    "lg.terms.p6": "Usługa, oprogramowanie, dokumentacja i znaki towarowe są własnością sprzedawcy. Udzielamy ograniczonego, niewyłącznego i niezbywalnego prawa do korzystania z usługi w ramach wybranego planu.",
    "lg.terms.h7": "7. Ograniczenie odpowiedzialności",
    "lg.terms.p7": "W zakresie dozwolonym przez prawo nie ponosimy odpowiedzialności za szkody pośrednie; całkowita odpowiedzialność jest ograniczona do kwoty zapłaconej w ciągu ostatnich 12 miesięcy. Nie dotyczy to oszustwa ani szkód na życiu i zdrowiu.",
    "lg.terms.h8": "8. Zawieszenie dostępu",
    "lg.terms.p8": "Możemy zawiesić lub zakończyć dostęp w przypadku istotnego naruszenia niniejszych warunków, braku płatności lub ryzyka naruszenia bezpieczeństwa czy oszustwa.",
    "lg.terms.h9": "9. Kontakt",
    "lg.terms.p9": "W przypadku pytań dotyczących niniejszych warunków skontaktuj się: Aleksandr Smirnov, za pośrednictwem kanałów pomocy w aplikacji.",
    "lg.privacy.title": "Polityka prywatności",
    "lg.privacy.updated": "Ostatnia aktualizacja: 26 sierpnia 2026",
    "lg.privacy.h1": "1. Administrator danych",
    "lg.privacy.p1": "Administratorem Twoich danych osobowych jest Aleksandr Smirnov, dostawca usługi GYMS.LIFE.",
    "lg.privacy.h2": "2. Jakie dane zbieramy",
    "lg.privacy.li2a": "Dane konta: imię i nazwisko, adres e-mail, dane logowania.",
    "lg.privacy.li2b": "Dane profilu: wiek, wzrost, waga, cel, doświadczenie, sprzęt, preferencje żywieniowe.",
    "lg.privacy.li2c": "Dane dotyczące aktywności: dzienniki treningów i odżywiania, wpisy o samopoczuciu, wskaźniki zdrowotne (jeśli zostały zaimportowane).",
    "lg.privacy.li2d": "Dane techniczne: identyfikatory urządzeń, adres IP, telemetria użytkowania.",
    "lg.privacy.h3": "3. Jak wykorzystujemy dane",
    "lg.privacy.li3a": "W celu utworzenia konta i świadczenia usługi (wykonanie umowy).",
    "lg.privacy.li3b": "W celu generowania spersonalizowanych planów treningowych i żywieniowych (wykonanie umowy).",
    "lg.privacy.li3c": "W celach bezpieczeństwa i zapobiegania oszustwom (prawnie uzasadniony interes).",
    "lg.privacy.li3d": "W celu ulepszania usługi (prawnie uzasadniony interes).",
    "lg.privacy.li3e": "W ramach obsługi klienta (wykonanie umowy).",
    "lg.privacy.h4": "4. Komu udostępniamy dane",
    "lg.privacy.li4a": "Dostawcom usług (hosting, bazy danych, analityka).",
    "lg.privacy.li4b": "Paddle – naszemu Merchant of Record, który obsługuje subskrypcje, płatności, podatki i faktury.",
    "lg.privacy.li4c": "Profesjonalnym doradcom (prawnicy, księgowi).",
    "lg.privacy.li4d": "Organom państwowym, gdy wymaga tego prawo.",
    "lg.privacy.h5": "5. Przechowywanie danych",
    "lg.privacy.p5": "Przechowujemy dane tak długo, jak jest to konieczne do świadczenia usługi oraz zgodnie z wymogami prawa; dane, które nie są już potrzebne, są usuwane lub anonimizowane.",
    "lg.privacy.h6": "6. Twoje prawa (UE/RODO)",
    "lg.privacy.p6": "Masz prawo do dostępu, sprostowania, usunięcia, ograniczenia przetwarzania, przenoszenia danych, wniesienia sprzeciwu, wycofania zgody oraz wniesienia skargi do organu nadzorczego. Na wnioski odpowiadamy w ciągu 1 miesiąca.",
    "lg.privacy.h7": "7. Transfery międzynarodowe",
    "lg.privacy.p7": "Jeśli dane są przekazywane poza EOG, stosujemy odpowiednie zabezpieczenia (standardowe klauzule umowne lub decyzje o adekwatności).",
    "lg.privacy.h8": "8. Bezpieczeństwo",
    "lg.privacy.p8": "Stosujemy odpowiednie środki techniczne i organizacyjne: szyfrowanie, kontrolę dostępu, monitorowanie.",
    "lg.privacy.h9": "9. Pliki cookie",
    "lg.privacy.p9": "Używamy niezbędnych plików cookie (sesja, uwierzytelnianie). Możesz zmienić ustawienia w swojej przeglądarce.",
    "lg.refund.title": "Polityka zwrotów",
    "lg.refund.updated": "Ostatnia aktualizacja: 26 sierpnia 2026",
    "lg.refund.h1": "30-dniowa gwarancja",
    "lg.refund.p1": "Oferujemy 30-dniową gwarancję zwrotu pieniędzy. Jeśli to nie dla Ciebie, zwrócimy pełną kwotę w ciągu 30 dni od daty zamówienia, bez żadnych dodatkowych warunków.",
    "lg.refund.h2": "Jak poprosić o zwrot",
    "lg.refund.p2a": "Zwroty są przetwarzane przez naszego partnera płatniczego Paddle. Aby poprosić o zwrot, odwiedź stronę",
    "lg.refund.p2b": "lub skontaktuj się z nami za pośrednictwem kanałów pomocy w aplikacji.",
    "lg.refund.h3": "Anulowanie subskrypcji",
