    "lg.nav.pricing": "Preise",
    "lg.terms.title": "Nutzungsbedingungen",
    "lg.terms.updated": "Zuletzt aktualisiert: 26. August 2026",
    "lg.terms.h1": "1. Verkäufer",
    "lg.terms.p1": "Der GYMS.LIFE-Dienst wird von Aleksandr Smirnov (im Folgenden „wir“) bereitgestellt. Durch die Nutzung des Dienstes schließen Sie einen Vertrag mit diesem Verkäufer ab. Wenn Sie den Dienst weiterhin nutzen, stimmen Sie diesen Bedingungen zu.",
    "lg.terms.h2": "2. Der Dienst",
    "lg.terms.p2": "GYMS.LIFE ist eine Plattform für persönliches Training und Ernährungsplanung: Trainingsprogramme, eine Übungsbibliothek mit Video-Tutorials, Ernährungspläne, Supplement-Pläne, Gesundheitseinblicke und Formanalyse. Der Dienst wird im Ist-Zustand („as is“) bereitgestellt; wir garantieren keinen ununterbrochenen oder fehlerfreien Betrieb. Die Inhalte stellen keine medizinische Beratung dar – konsultieren Sie vor einer Änderung Ihrer körperlichen Aktivität oder Ernährung einen Arzt.",
    "lg.terms.h3": "3. Konto",
    "lg.terms.p3": "Sie müssen Ihre Anmeldedaten sicher aufbewahren und sind für alle Aktivitäten auf Ihrem Konto verantwortlich. Die von Ihnen angegebenen Informationen müssen korrekt sein.",
    "lg.terms.h4": "4. Zahlungen und Abonnement",
    "lg.terms.p4a": "Der Bestellvorgang wird von unserem Online-Wiederverkäufer Paddle.com abgewickelt. Paddle.com ist der Merchant of Record für alle unsere Bestellungen. Paddle übernimmt den gesamten Kundenservice für zahlungsbezogene Anfragen und wickelt Rückerstattungen ab. Zahlungs-, Abrechnungs-, Steuer-, Kündigungs- und Erstattungsmodalitäten unterliegen den",
    "lg.terms.p4link": "Käuferbedingungen von Paddle",
    "lg.terms.p4b": "Das Abonnement verlängert sich automatisch um den gewählten Zeitraum (Woche / Monat / Jahr), bis Sie es kündigen. Sie können jederzeit kündigen – der Zugriff bleibt bis zum Ende des bezahlten Zeitraums bestehen.",
    "lg.terms.h5": "5. Verbotene Aktivitäten",
    "lg.terms.p5": "Es ist untersagt, den Dienst rechtswidrig zu nutzen, Spam zu verbreiten, geistiges Eigentum zu verletzen, Sicherheitsverletzungen zu versuchen (Malware, System-Probing, Data Scraping) oder die Inhalte des Dienstes zu kopieren oder weiterzuverkaufen.",
    "lg.terms.h6": "6. Geistiges Eigentum",
    "lg.terms.p6": "Der Dienst, die Software, die Dokumentation und die Marken sind Eigentum des Verkäufers. Wir gewähren ein beschränktes, nicht exklusives, nicht übertragbares Recht zur Nutzung des Dienstes im Rahmen des gewählten Abonnements.",
    "lg.terms.h7": "7. Haftungsbeschränkung",
    "lg.terms.p7": "Soweit gesetzlich zulässig, haften wir nicht für mittelbare Schäden; die Gesamthaftung ist auf den in den letzten 12 Monaten gezahlten Betrag beschränkt. Dies gilt nicht bei Vorsatz, Arglist oder Schäden an Leben, Körper und Gesundheit.",
    "lg.terms.h8": "8. Sperrung des Zugangs",
    "lg.terms.p8": "Wir können den Zugang bei einer wesentlichen Verletzung dieser Bedingungen, bei Zahlungsverzug oder bei Sicherheits- bzw. Betrugsrisiken sperren oder kündigen.",
    "lg.terms.h9": "9. Kontakt",
    "lg.terms.p9": "Bei Fragen zu diesen Bedingungen wenden Sie sich an: Aleksandr Smirnov, über die Support-Kanäle der App.",
    "lg.privacy.title": "Datenschutzerklärung",
    "lg.privacy.updated": "Zuletzt aktualisiert: 26. August 2026",
    "lg.privacy.h1": "1. Verantwortlicher",
    "lg.privacy.p1": "Verantwortlicher für Ihre personenbezogenen Daten ist Aleksandr Smirnov, Anbieter des Dienstes GYMS.LIFE.",
    "lg.privacy.h2": "2. Welche Daten wir erheben",
    "lg.privacy.li2a": "Kontodaten: Name, E-Mail, Anmeldedaten.",
    "lg.privacy.li2b": "Profildaten: Alter, Größe, Gewicht, Ziel, Trainingserfahrung, Ausrüstung, Ernährungsvorlieben.",
    "lg.privacy.li2c": "Aktivitätsdaten: Trainings- und Ernährungsprotokolle, Wohlbefinden-Einträge, Gesundheitsdaten (falls importiert).",
    "lg.privacy.li2d": "Technische Daten: Gerätekennungen, IP-Adresse, Nutzungstelemetrie.",
    "lg.privacy.h3": "3. Wie wir die Daten nutzen",
    "lg.privacy.li3a": "Zur Erstellung eines Kontos und Bereitstellung des Dienstes (Vertragserfüllung).",
    "lg.privacy.li3b": "Zur Erstellung personalisierter Trainings- und Ernährungspläne (Vertragserfüllung).",
    "lg.privacy.li3c": "Für Sicherheit und Betrugsprävention (berechtigtes Interesse).",
    "lg.privacy.li3d": "Zur Verbesserung des Dienstes (berechtigtes Interesse).",
    "lg.privacy.li3e": "Für den Kundensupport (Vertragserfüllung).",
    "lg.privacy.h4": "4. Mit wem wir Daten teilen",
    "lg.privacy.li4a": "Dienstleister (Hosting, Datenbank, Analysen).",
    "lg.privacy.li4b": "Paddle – unser Merchant of Record, der Abonnements, Zahlungen, Steuern und Rechnungen abwickelt.",
    "lg.privacy.li4c": "Professionelle Berater (Rechtsanwälte, Steuerberater).",
    "lg.privacy.li4d": "Staatliche Behörden, sofern gesetzlich vorgeschrieben.",
    "lg.privacy.h5": "5. Speicherdauer",
    "lg.privacy.p5": "Wir speichern Daten so lange, wie es für die Bereitstellung des Dienstes erforderlich und gesetzlich vorgeschrieben ist; nicht mehr benötigte Daten werden gelöscht oder anonymisiert.",
    "lg.privacy.h6": "6. Ihre Rechte (EU/DSGVO)",
    "lg.privacy.p6": "Sie haben das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit, Widerspruch, Widerruf der Einwilligung und Beschwerde bei einer Aufsichtsbehörde. Wir beantworten Anfragen innerhalb eines Monats.",
    "lg.privacy.h7": "7. Internationale Übermittlungen",
    "lg.privacy.p7": "Bei einer Übermittlung von Daten außerhalb des EWR wenden wir angemessene Sicherheitsvorkehrungen an (Standardvertragsklauseln oder Angemessenheitsbeschlüsse).",
    "lg.privacy.h8": "8. Sicherheit",
    "lg.privacy.p8": "Wir wenden geeignete technische und organisatorische Maßnahmen an: Verschlüsselung, Zugriffskontrolle, Überwachung.",
    "lg.privacy.h9": "9. Cookies",
    "lg.privacy.p9": "Wir verwenden essenzielle Cookies (Sitzung, Authentifizierung). Sie können die Einstellungen in Ihrem Browser anpassen.",
    "lg.refund.title": "Rückerstattungsrichtlinie",
    "lg.refund.updated": "Zuletzt aktualisiert: 26. August 2026",
    "lg.refund.h1": "30-Tage-Garantie",
    "lg.refund.p1": "Wir bieten eine 30-Tage-Geld-zurück-Garantie. Wenn es nicht zu Ihnen passt, erstatten wir den vollen Betrag innerhalb von 30 Tagen ab Bestelldatum – ohne zusätzliche Bedingungen.",
    "lg.refund.h2": "So fordern Sie eine Rückerstattung an",
    "lg.refund.p2a": "Rückerstattungen werden von unserem Zahlungspartner Paddle abgewickelt. Um eine Rückerstattung zu beantragen, besuchen Sie",
    "lg.refund.p2b": "oder kontaktieren Sie uns über die Support-Kanäle der App.",
    "lg.refund.h3": "Abonnement kündigen",
    "lg.refund.p3a": "Sie können Ihr Abonnement jederzeit in den Kontoeinstellungen kündigen („Abonnement verwalten“). Nach der Kündigung bleibt der Zugriff bis zum Ende des bezahlten Zeitraums erhalten; es werden keine weiteren Zahlungen eingezogen. Die",
    "lg.refund.p3link": "Rückerstattungsrichtlinie von Paddle",
    "lg.refund.p3b": "gilt ebenfalls.",
