    "hw.ins.hrv.cause.bad": "HRV liegt weit unter deinem Normalwert — starke Sympathikus-Dominanz, das klassische Zeichen für Überlastung oder eine anbahnende Krankheit.",
    "hw.ins.hrv.effect.good": "Volle oder +5% Belastung ist erlaubt: Du kannst bei der Hauptübung mehr Gewicht auflegen.",
    "hw.ins.hrv.effect.watch": "Belastung sinkt um ca. 10%: gleiches Gewicht, ein Satz weniger.",
    "hw.ins.hrv.effect.bad": "Belastung sinkt auf 65–80%: Technikfokus, maximal RPE 7, keine Sätze bis zum Muskelversagen.",
    "hw.ins.rhr.cause.good": "Ruhepuls ist normal oder niedriger — dein Herz hat sich erholt, Hydration und Körpertemperatur passen.",
    "hw.ins.rhr.cause.bad": "Ruhepuls liegt {delta}über deiner Norm — häufige Ursachen: Schlafmangel, Dehydrierung, Hitze, Alkohol oder eine beginnende Infektion.",
    "hw.ins.rhr.effect.good": "Konditionstraining und schwere Sätze sind ohne Einschränkungen möglich.",
    "hw.ins.rhr.effect.watch": "Satzpausen werden verlängert (+30 s) und intensive Einheiten gekürzt.",
    "hw.ins.rhr.effect.bad": "Kein HIIT und keine Maximalbelastungen heute — stattdessen lockere Bewegung und viel trinken.",
    "hw.ins.sleep.targetCompare": "Ziel: 7,5–9 Std.",
    "hw.ins.sleep.cause.good": "Du hast ausreichend geschlafen — der Großteil der Wachstumshormone wird im Tiefschlaf ausgeschüttet und die Muskelproteinsynthese lief optimal.",
    "hw.ins.sleep.cause.watch": "Etwas zu wenig Schlaf — Glykogenresynthese und Fokus sinken, die Technik leidet in den letzten Sätzen.",
    "hw.ins.sleep.cause.bad": "Erheblicher Schlafmangel — Testosteron/Cortisol-Verhältnis verschlechtert sich, Kraft sinkt um 3–8% und das Verletzungsrisiko steigt.",
    "hw.ins.sleep.effect.good": "Geplantes Volumen bleibt bei 100%.",
    "hw.ins.sleep.effect.watch": "Bei jeder Nebenübung wird ein Satz gestrichen.",
    "hw.ins.sleep.effect.bad": "Die Einheit wird auf die Hauptübungen reduziert, Gewicht um 10–20% gesenkt, kein Muskelversagen.",
    "hw.ins.quality.compare": "subjektive Bewertung",
    "hw.ins.quality.cause": "Fragmentierter Schlaf verkürzt die Tiefschlafphasen, sodass sich das zentrale Nervensystem langsamer erholt, als die reinen Stunden vermuten lassen.",
    "hw.ins.quality.effect.good": "Explosive Übungen (Sprünge, Sprints) sind erlaubt.",
