    "h2.why": "Warum gibt es keinen Button „Mit Apple Health / Google Fit verbinden“?",
    "h2.whyText": "Apple Health hat keine Web-API – Daten verlassen das Smartphone niemals ohne deine Aktion, und die Google Fit API wird eingestellt (keine neuen Apps, Support endet 2026). Daher bietet diese Seite drei funktionierende Wege: automatischer Push vom Smartphone (iOS-Kurzbefehle / Health Connect), Datei-Import und Kamera-Messung.",
