    "lg.nav.pricing": "Precios",
    "lg.terms.title": "Términos del servicio",
    "lg.terms.updated": "Última actualización: 26 de agosto de 2026",
    "lg.terms.h1": "1. Vendedor",
    "lg.terms.p1": "El servicio GYMS.LIFE es proporcionado por Aleksandr Smirnov (en adelante, «nosotros»). Al utilizar el servicio, celebras un acuerdo con este vendedor. Al continuar utilizando el servicio, aceptas estos términos.",
    "lg.terms.h2": "2. El servicio",
    "lg.terms.p2": "GYMS.LIFE es una plataforma de entrenamiento personal y planificación nutricional: programas de entrenamiento, biblioteca de ejercicios con videotutoriales, planes de comidas, programación de suplementos, análisis de salud y corrección de técnica. El servicio se proporciona «tal cual»; no garantizamos un funcionamiento ininterrumpido ni libre de errores. El contenido no constituye asesoramiento médico; consulta a un médico antes de cambiar tu actividad física o dieta.",
    "lg.terms.h3": "3. Cuenta",
    "lg.terms.p3": "Debes mantener seguras tus credenciales de inicio de sesión y eres responsable de la actividad en tu cuenta. La información que proporciones debe ser precisa.",
    "lg.terms.h4": "4. Pagos y suscripción",
    "lg.terms.p4a": "El proceso de pedido es gestionado por nuestro revendedor en línea Paddle.com. Paddle.com es el Merchant of Record para todos nuestros pedidos. Paddle proporciona todo el servicio de atención al cliente para consultas relacionadas con pagos y gestiona los reembolsos. La mecánica de pagos, facturación, impuestos, cancelaciones y reembolsos se rige por",
    "lg.terms.p4link": "los términos de comprador de Paddle",
    "lg.terms.p4b": "La suscripción se renueva automáticamente durante el período elegido (semana / mes / año) hasta que la canceles. Puedes cancelar en cualquier momento; el acceso se mantiene hasta el final del período pagado.",
    "lg.terms.h5": "5. Actividades prohibidas",
    "lg.terms.p5": "Está prohibido utilizar el servicio de forma ilícita, distribuir spam, infringir la propiedad intelectual, intentar vulnerar la seguridad (malware, escaneo de sistemas, extracción de datos) o copiar y revender el contenido del servicio.",
    "lg.terms.h6": "6. Propiedad intelectual",
    "lg.terms.p6": "El servicio, el software, la documentación y las marcas comerciales son propiedad del vendedor. Otorgamos un derecho limitado, no exclusivo e intransferible para usar el servicio bajo el plan elegido.",
    "lg.terms.h7": "7. Limitación de responsabilidad",
    "lg.terms.p7": "En la medida permitida por la ley, no nos hacemos responsables de pérdidas indirectas; la responsabilidad total se limita a la cantidad pagada en los últimos 12 meses. Esto no aplica a casos de fraude o daños a la vida y la salud.",
    "lg.terms.h8": "8. Suspensión del acceso",
    "lg.terms.p8": "Podemos suspender o cancelar el acceso en caso de incumplimiento sustancial de estos términos, falta de pago o riesgo de seguridad o fraude.",
    "lg.terms.h9": "9. Contacto",
    "lg.terms.p9": "Para preguntas sobre estos términos, contacta a: Aleksandr Smirnov, a través de los canales de soporte de la app.",
    "lg.privacy.title": "Política de privacidad",
    "lg.privacy.updated": "Última actualización: 26 de agosto de 2026",
    "lg.privacy.h1": "1. Responsable del tratamiento",
    "lg.privacy.p1": "El responsable del tratamiento de tus datos personales es Aleksandr Smirnov, proveedor del servicio GYMS.LIFE.",
    "lg.privacy.h2": "2. Qué datos recopilamos",
    "lg.privacy.li2a": "Datos de la cuenta: nombre, correo electrónico, información de inicio de sesión.",
    "lg.privacy.li2b": "Datos del perfil: edad, altura, peso, objetivo, experiencia, equipamiento, preferencias dietéticas.",
    "lg.privacy.li2c": "Datos de actividad: registros de entrenamiento y nutrición, entradas de bienestar, métricas de salud (si se importan).",
    "lg.privacy.li2d": "Datos técnicos: identificadores de dispositivo, dirección IP, telemetría de uso.",
    "lg.privacy.h3": "3. Cómo los usamos",
    "lg.privacy.li3a": "Para crear una cuenta y prestar el servicio (ejecución de contrato).",
    "lg.privacy.li3b": "Para generar planes personalizados de entrenamiento y nutrición (ejecución de contrato).",
    "lg.privacy.li3c": "Para seguridad y prevención de fraudes (interés legítimo).",
    "lg.privacy.li3d": "Para mejorar el servicio (interés legítimo).",
    "lg.privacy.li3e": "Para atención al cliente (ejecución de contrato).",
    "lg.privacy.h4": "4. Con quién compartimos los datos",
    "lg.privacy.li4a": "Proveedores de servicios (alojamiento, bases de datos, analítica).",
    "lg.privacy.li4b": "Paddle – nuestro Merchant of Record, que gestiona suscripciones, pagos, impuestos y facturas.",
    "lg.privacy.li4c": "Asesores profesionales (abogados, contables).",
    "lg.privacy.li4d": "Autoridades gubernamentales, cuando lo exija la ley.",
    "lg.privacy.h5": "5. Conservación",
    "lg.privacy.p5": "Conservamos los datos durante el tiempo necesario para prestar el servicio y según lo exija la ley; los datos que ya no se necesitan se eliminan o se anonimizan.",
    "lg.privacy.h6": "6. Tus derechos (UE/RGPD)",
    "lg.privacy.p6": "Tienes derecho a acceder, rectificar, suprimir, limitar el tratamiento, portar tus datos, oponerte, retirar el consentimiento y presentar una reclamación ante una autoridad de control. Respondemos a las solicitudes en un plazo de 1 mes.",
    "lg.privacy.h7": "7. Transferencias internacionales",
    "lg.privacy.p7": "Si los datos se transfieren fuera del EEE, aplicamos las salvaguardas adecuadas (cláusulas contractuales tipo o decisiones de adecuación).",
    "lg.privacy.h8": "8. Seguridad",
    "lg.privacy.p8": "Aplicamos las medidas técnicas y organizativas adecuadas: cifrado, control de acceso, monitorización.",
    "lg.privacy.h9": "9. Cookies",
    "lg.privacy.p9": "Utilizamos cookies esenciales (sesión, autenticación). Puedes cambiar los ajustes en tu navegador.",
    "lg.refund.title": "Política de reembolso",
    "lg.refund.updated": "Última actualización: 26 de agosto de 2026",
    "lg.refund.h1": "Garantía de 30 días",
    "lg.refund.p1": "Ofrecemos una garantía de devolución de dinero de 30 días. Si no es para ti, te reembolsaremos el importe total dentro de los 30 días posteriores a la fecha del pedido, sin condiciones adicionales.",
    "lg.refund.h2": "Cómo solicitar un reembolso",
    "lg.refund.p2a": "Los reembolsos son procesados por nuestro socio de pagos Paddle. Para solicitar un reembolso, visita",
    "lg.refund.p2b": "o contáctanos a través de los canales de soporte de la app.",
    "lg.refund.h3": "Cancelar tu suscripción",
    "lg.refund.p3a": "Puedes cancelar tu suscripción en cualquier momento en los ajustes de la cuenta (\"Gestionar suscripción\"). Tras la cancelación, el acceso se mantiene hasta el final del período pagado; no se realizarán más cobros. La",
    "lg.refund.p3link": "política de reembolso de Paddle",
    "lg.refund.p3b": "también es aplicable.",
