    "lg.nav.pricing": "Tarifs",
    "lg.terms.title": "Conditions d'utilisation",
    "lg.terms.updated": "Dernière mise à jour : 26 août 2026",
    "lg.terms.h1": "1. Vendeur",
    "lg.terms.p1": "Le service GYMS.LIFE est fourni par Aleksandr Smirnov (ci-après – « nous »). En utilisant ce service, vous concluez un accord avec ce vendeur. En continuant à utiliser le service, vous acceptez ces conditions.",
    "lg.terms.h2": "2. Le Service",
    "lg.terms.p2": "GYMS.LIFE est une plateforme d'entraînement personnalisé et de planification nutritionnelle : programmes d'entraînement, bibliothèque d'exercices avec tutoriels vidéo, plans de repas, planification des compléments, indicateurs de santé et analyse de la posture. Le service est fourni « en l'état » ; nous ne garantissons pas un fonctionnement ininterrompu ou sans erreur. Le contenu ne constitue pas un avis médical — consultez un médecin avant de modifier votre activité physique ou votre alimentation.",
    "lg.terms.h3": "3. Compte",
    "lg.terms.p3": "Vous devez préserver la confidentialité de vos identifiants et êtes responsable de l'activité sur votre compte. Les informations fournies doivent être exactes.",
    "lg.terms.h4": "4. Paiements et abonnement",
    "lg.terms.p4a": "Le processus de commande est géré par notre revendeur en ligne Paddle.com. Paddle.com est le marchand officiel (Merchant of Record) pour toutes nos commandes. Paddle assure l'ensemble du service client lié aux paiements et gère les remboursements. Les modalités de paiement, de facturation, de taxes, d'annulation et de remboursement sont régies par",
    "lg.terms.p4link": "les conditions pour acheteurs de Paddle",
    "lg.terms.p4b": "L'abonnement se renouvelle automatiquement pour la période choisie (semaine / mois / an) jusqu'à sa résiliation. Vous pouvez annuler à tout moment – l'accès reste actif jusqu'à la fin de la période payée.",
    "lg.terms.h5": "5. Activités interdites",
    "lg.terms.p5": "Il est interdit d'utiliser le service de manière illicite, de diffuser du spam, de porter atteinte à la propriété intellectuelle, de tenter de compromettre la sécurité (logiciels malveillants, analyse de vulnérabilités, scraping de données) ou de copier et revendre le contenu du service.",
    "lg.terms.h6": "6. Propriété intellectuelle",
    "lg.terms.p6": "Le service, les logiciels, la documentation et les marques sont la propriété du vendeur. Nous vous accordons un droit d'utilisation limité, non exclusif et non transférable dans le cadre du forfait choisi.",
    "lg.terms.h7": "7. Limitation de responsabilité",
    "lg.terms.p7": "Dans la mesure permise par la loi, nous ne saurions être tenus responsables des préjudices indirects ; la responsabilité totale est limitée au montant payé au cours des 12 derniers mois. Cela ne s'applique pas aux cas de fraude ou de dommages corporels.",
    "lg.terms.h8": "8. Suspension de l'accès",
    "lg.terms.p8": "Nous nous réservons le droit de suspendre ou d'interrompre l'accès en cas de manquement grave aux présentes conditions, de défaut de paiement ou de risque de sécurité ou de fraude.",
    "lg.terms.h9": "9. Contact",
    "lg.terms.p9": "Pour toute question concernant ces conditions, contactez : Aleksandr Smirnov, via les canaux d'assistance de l'application.",
    "lg.privacy.title": "Politique de confidentialité",
    "lg.privacy.updated": "Dernière mise à jour : 26 août 2026",
    "lg.privacy.h1": "1. Responsable du traitement",
    "lg.privacy.p1": "Le responsable du traitement de vos données personnelles est Aleksandr Smirnov, éditeur du service GYMS.LIFE.",
    "lg.privacy.h2": "2. Données collectées",
    "lg.privacy.li2a": "Données de compte : nom, adresse e-mail, identifiants de connexion.",
    "lg.privacy.li2b": "Données de profil : âge, taille, poids, objectif, expérience, équipement, préférences alimentaires.",
    "lg.privacy.li2c": "Données d'activité : journaux d'entraînement et de nutrition, entrées de bien-être, indicateurs de santé (si importés).",
    "lg.privacy.li2d": "Données techniques : identifiants de l'appareil, adresse IP, télémétrie d'utilisation.",
    "lg.privacy.h3": "3. Utilisation des données",
    "lg.privacy.li3a": "Créer un compte et fournir le service (exécution du contrat).",
    "lg.privacy.li3b": "Générer des programmes d'entraînement et de nutrition personnalisés (exécution du contrat).",
    "lg.privacy.li3c": "Assurer la sécurité et prévenir la fraude (intérêt légitime).",
    "lg.privacy.li3d": "Améliorer le service (intérêt légitime).",
    "lg.privacy.li3e": "Fournir une assistance client (exécution du contrat).",
    "lg.privacy.h4": "4. Partage des données",
    "lg.privacy.li4a": "Prestataires de services (hébergement, base de données, analyses).",
    "lg.privacy.li4b": "Paddle – notre marchand officiel, qui gère les abonnements, les paiements, les taxes et la facturation.",
    "lg.privacy.li4c": "Conseillers professionnels (avocats, experts-comptables).",
    "lg.privacy.li4d": "Autorités publiques, lorsque la loi l'exige.",
    "lg.privacy.h5": "5. Conservation",
    "lg.privacy.p5": "Nous conservons les données aussi longtemps que nécessaire pour fournir le service et respecter nos obligations légales ; les données devenues inutiles sont supprimées ou anonymisées.",
    "lg.privacy.h6": "6. Vos droits (UE/RGPD)",
    "lg.privacy.p6": "Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation du traitement, de portabilité des données, d'opposition, de retrait du consentement et d'introduire une réclamation auprès d'une autorité de contrôle. Nous répondons aux demandes dans un délai d'un mois.",
    "lg.privacy.h7": "7. Transferts internationaux",
    "lg.privacy.p7": "En cas de transfert de données hors de l'EEE, nous appliquons les garanties appropriées (clauses contractuelles types ou décisions d'adéquation).",
    "lg.privacy.h8": "8. Sécurité",
    "lg.privacy.p8": "Nous mettons en œuvre des mesures techniques et organisationnelles adaptées : chiffrement, contrôle des accès, surveillance.",
    "lg.privacy.h9": "9. Cookies",
    "lg.privacy.p9": "Nous utilisons des cookies essentiels (session, authentification). Vous pouvez modifier vos préférences dans votre navigateur.",
    "lg.refund.title": "Politique de remboursement",
    "lg.refund.updated": "Dernière mise à jour : 26 août 2026",
    "lg.refund.h1": "Garantie de 30 jours",
    "lg.refund.p1": "Nous offrons une garantie satisfait ou remboursé de 30 jours. Si cela ne vous convient pas, nous vous remboursons intégralement dans les 30 jours suivant la commande, sans condition supplémentaire.",
    "lg.refund.h2": "Comment demander un remboursement",
    "lg.refund.p2a": "Les remboursements sont traités par notre partenaire de paiement Paddle. Pour demander un remboursement, rendez-vous sur",
    "lg.refund.p2b": "ou contactez-nous via les canaux d'assistance de l'application.",
    "lg.refund.h3": "Résiliation de votre abonnement",
    "lg.refund.p3a": "Vous pouvez résilier votre abonnement à tout moment dans les paramètres de votre compte (« Gérer l'abonnement »). Après résiliation, l'accès reste actif jusqu'à la fin de la période payée ; aucun autre prélèvement ne sera effectué. La",
    "lg.refund.p3link": "politique de remboursement de Paddle",
    "lg.refund.p3b": "s'applique également.",
